```js
(function(){
  var KEY='huerta-carrito-v1';
  var MIN=20;
  var lista=document.getElementById('carrito-lista');
  var vacio=document.getElementById('carrito-vacio');
  var totalEl=document.getElementById('carrito-total');
  var aviso=document.getElementById('carrito-aviso');
  var form=document.getElementById('form-pedido');
  var detalle=document.getElementById('pedido-detalle');
  var totalInput=document.getElementById('pedido-total');
  var estado=document.getElementById('pedido-estado');
  if(!lista||!form) return;

  var carrito=[];
  try{ var raw=localStorage.getItem(KEY); if(raw) carrito=JSON.parse(raw)||[]; }catch(e){ carrito=[]; }
  if(!Array.isArray(carrito)) carrito=[];

  function guardar(){ try{ localStorage.setItem(KEY, JSON.stringify(carrito)); }catch(e){} }
  function total(){ return carrito.reduce(function(s,i){ return s+i.precio*i.cant; },0); }
  function money(n){ return '$'+ (Math.round(n*100)/100).toString().replace('.',','); }
```

