  function pintar(){
    lista.innerHTML='';
    carrito.forEach(function(item,idx){
      var li=document.createElement('li');
      li.className='cart-row';
      li.innerHTML='<div class="cart-info"><span class="cart-name"></span><span class="cart-price"></span></div>'+
